"use client";

import { cn } from "@/lib/utils";
import type { Variants } from "motion/react";
import {
 LazyMotion,
 domMin,
 m,
 useAnimation,
 useReducedMotion,
} from "motion/react";
import {
 forwardRef,
 useCallback,
 useImperativeHandle,
 useRef,
 type HTMLAttributes,
} from "react";
export interface NetworkIconHandle {
 startAnimation: () => void;
 stopAnimation: () => void;
}

interface NetworkIconProps extends Omit<
 HTMLAttributes<HTMLDivElement>,
 | "color"
 | "onDrag"
 | "onDragStart"
 | "onDragEnd"
 | "onAnimationStart"
 | "onAnimationEnd"
 | "onAnimationIteration"
> {
 size?: number;
 duration?: number;
 isAnimated?: boolean;
 color?: string;
}

const NetworkIcon = forwardRef<NetworkIconHandle, NetworkIconProps>(
 (
  {
   onMouseEnter,
   onMouseLeave,
   className,
   size = 24,
   duration = 1,
   isAnimated = true,
   color,
   ...props
  },
  ref,
 ) => {
  const controls = useAnimation();
  const reduced = useReducedMotion();
  const isControlled = useRef(false);

  useImperativeHandle(ref, () => {
   isControlled.current = true;
   return {
    startAnimation: () =>
     reduced ? controls.start("normal") : controls.start("animate"),
    stopAnimation: () => controls.start("normal"),
   };
  });

  const handleEnter = useCallback(
   (e?: React.MouseEvent<HTMLDivElement>) => {
    if (!isAnimated || reduced) return;
    if (!isControlled.current) controls.start("animate");
    else onMouseEnter?.(e as any);
   },
   [controls, reduced, isAnimated, onMouseEnter],
  );

  const handleLeave = useCallback(
   (e?: React.MouseEvent<HTMLDivElement>) => {
    if (!isControlled.current) controls.start("normal");
    else onMouseLeave?.(e as any);
   },
   [controls, onMouseLeave],
  );

  const nodeVariants: Variants = {
   normal: { scale: 1 },
   animate: (i: number) => ({
    scale: [1, 0, 1.15, 1],
    transition: {
     duration: 0.4 * duration,
     ease: "easeOut",
     times: [0, 0.2, 0.7, 1],
     delay: i * 0.3 * duration,
    },
   }),
  };

  const linkVariants: Variants = {
   normal: { pathLength: 1, opacity: 1 },
   animate: (i: number) => ({
    pathLength: [0, 1],
    opacity: [0, 1],
    transition: {
     duration: 0.3 * duration,
     ease: "easeOut",
     delay: (0.15 + i * 0.1) * duration,
    },
   }),
  };

  return (
   <LazyMotion features={domMin} strict>
    <m.div
     className={cn("inline-flex items-center justify-center", className)}
     onMouseEnter={handleEnter}
     onMouseLeave={handleLeave}
     {...props}
     style={{ color, ...props.style }}
    >
     <m.svg
      xmlns="http://www.w3.org/2000/svg"
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      animate={controls}
      initial="normal"
     >
      <m.rect
       x="16"
       y="16"
       width="6"
       height="6"
       rx="1"
       variants={nodeVariants}
       custom={1}
       style={{ transformBox: "view-box", originX: "19px", originY: "19px" }}
      />
      <m.rect
       x="2"
       y="16"
       width="6"
       height="6"
       rx="1"
       variants={nodeVariants}
       custom={1}
       style={{ transformBox: "view-box", originX: "5px", originY: "19px" }}
      />
      <m.rect
       x="9"
       y="2"
       width="6"
       height="6"
       rx="1"
       variants={nodeVariants}
       custom={0}
       style={{ transformBox: "view-box", originX: "12px", originY: "5px" }}
      />
      <m.path
       d="M5 16v-3a1 1 0 0 1 1-1h12a1 1 0 0 1 1 1v3"
       variants={linkVariants}
       custom={1}
      />
      <m.path d="M12 12V8" variants={linkVariants} custom={0} />
     </m.svg>
    </m.div>
   </LazyMotion>
  );
 },
);

NetworkIcon.displayName = "NetworkIcon";
export { NetworkIcon };
